//
// Drives the stdlib's pure-functional tmdd_step on the rapamycin/liver
// configuration (i=1, R_total_0 = 50 nM, K_d = 0.10 nM, k_on = 0.10
// L/(nmol·h)) at a fixed C_t_mass = 1.0e-3 mg/L plasma — the same
// concentration the parity ref reaches in the liver around t ≈ 6 h on the
// canonical Cypher elution. Confirms:
//
//   1. Receptor occupancy climbs monotonically from 0 toward saturation
//      under sustained drug exposure (kinetic plausibility).
//   2. R_free + DR ≈ R_total (mass conservation modulo synthesis &
//      internalisation; we don't expect bit-exact conservation because of
//      ksyn / kint, but the budget should be sane).
//   3. tmdd_occupancy() agrees with manually computed DR / (R_free + DR).
//
// Pure-Sounio, no external golden file: this guards the module's API surface
// against accidental drift. Numerical parity with the parity ref is enforced
// transitively by scripts/ci/dissertation_pbpk28_parity_gate.sh case 5 once
// the parity ref switches its inline tmdd_step_organ to import this module
// (planned G-ε-15 after the PBPK28 core lands).

use darwin_pbpk::tmdd::fkbp12_mtorc1::*

fn fmt_4(x: f64) -> i64 { return (x * 10000.0) as i64 }

fn main() with Mut, Div, IO {
    let p = fkbp12_params_at(1)        // liver
    var s = TmddState { ct_mass: 1.0e-3, rfree: fkbp12_rtotal0_at(1), dr: 0.0 }
    let dt = 0.5                       // hours per step
    let n_steps = 24                   // → 12 h total

    print("TMDD smoke — liver (i=1), R_total_0 = ")
    print(fkbp12_rtotal0_at(1) as i64)
    println(" nM, C_t fixed at 1e-3 mg/L")
    println("step  R_free(nM)   DR(nM)       occupancy")

    var step = 0
    while step < n_steps {
        s = tmdd_step(s, p, dt)
        // Re-pin C_t (this smoke isolates TMDD; PBPK transport would do this
        // job in the coupled simulation).
        s.ct_mass = 1.0e-3
        let occ = tmdd_occupancy(s)
        let total = s.rfree + s.dr
        let report = (step + 1) == 1 || (step + 1) == 6 || (step + 1) == 12 || (step + 1) == 24
        if report {
            print("step="); print(step + 1)
            print(" rfree*1e4="); print(fmt_4(s.rfree))
            print(" dr*1e4="); print(fmt_4(s.dr))
            print(" occ*1e4="); println(fmt_4(occ))
        }
        // Invariant checks at every step:
        let mut_ok = (s.rfree >= 0.0) && (s.dr >= 0.0)
        if !mut_ok {
            println("FAIL: negative state component")
            return
        }
        // Total receptor budget shouldn't explode — bound by 2× initial
        // (synthesis can grow the pool over many hours but not 2× in 12 h
        // at k_syn = 2.5 nM/h).
        if total > 100.0 {
            println("FAIL: receptor budget blew up")
            return
        }
        step = step + 1
    }

    // Final-state invariants.
    let occ_final = tmdd_occupancy(s)
    // Occupancy at C_t = 1.1 nM (≈ 1e-3 mg/L ÷ 914 Da/nmol), K_d = 0.1 nM →
    // saturation fraction at *equilibrium* ≈ 11/12 ≈ 0.92. At t=12 h with
    // k_on·C_t ≈ 0.11/h the binding timescale is τ ≈ 9 h, so 12 h reaches
    // only ~73% of the way — predicted occ ≈ 0.37-0.45. Allow [0.30, 0.70].
    let occ_ok = (occ_final > 0.30) && (occ_final < 0.70)
    if !occ_ok {
        print("FAIL: occupancy out of expected band [0.30, 0.70]: ")
        println(fmt_4(occ_final))
        return
    }

    println("TMDD_FKBP12_SMOKE_PASS")
}

//@ run-pass
// tests/run-pass/display_headless.sio — Headless canvas smoke test
//
// Exercises stdlib/display/canvas + stdlib/display/font without opening
// a window, writing pixels to a heap buffer and verifying values.
//
// Expected output:
//   DISPLAY_HEADLESS_PASS
//   exit 0

use display::canvas::{Canvas, canvas_clear, canvas_set_pixel, canvas_fill_rect,
                       canvas_draw_line, canvas_draw_circle, canvas_fill_circle,
                       canvas_draw_char, canvas_draw_text}
use display::font::{font_glyph, font_draw_char}

fn make_headless_canvas(w: i64, h: i64) -> Canvas with Alloc {
    let pix = heap_alloc(w * h * 8) as *mut i64
    Canvas { pixels: pix, width: w, height: h }
}

fn read_pixel(c: &Canvas, x: i64, y: i64) -> i64 {
    read_i64(c.pixels, y * c.width + x)
}

fn main() with IO, Alloc, Mut, Div {
    let w: i64 = 128
    let h: i64 = 128
    var c = make_headless_canvas(w, h)

    // 1. canvas_clear
    canvas_clear(&!c, 10, 20, 30)
    let p0 = read_pixel(&c, 0, 0)
    let expected_clear = 30 | (20 << 8) | (10 << 16)
    assert(p0 == expected_clear)

    // 2. canvas_set_pixel
    canvas_set_pixel(&!c, 64, 64, 255, 0, 0)
    let p1 = read_pixel(&c, 64, 64)
    let expected_red = 0 | (0 << 8) | (255 << 16)
    assert(p1 == expected_red)

    // 3. canvas_fill_rect — paint a 10×10 blue square at (5,5)
    canvas_fill_rect(&!c, 5, 5, 10, 10, 0, 0, 255)
    let corner = read_pixel(&c, 5, 5)
    let expected_blue = 255 | (0 << 8) | (0 << 16)
    assert(corner == expected_blue)
    // Pixel just outside rect should still be clear background
    let outside = read_pixel(&c, 15, 15)
    assert(outside == expected_clear)

    // 4. canvas_draw_line — draws at least one pixel along y=0 row
    canvas_clear(&!c, 0, 0, 0)
    canvas_draw_line(&!c, 0, 50, 127, 50, 200, 150, 100)
    let line_px = read_pixel(&c, 64, 50)
    let expected_line = 100 | (150 << 8) | (200 << 16)
    assert(line_px == expected_line)

    // 5. canvas_draw_circle — centre pixel won't be filled; check a nearby spoke
    canvas_clear(&!c, 0, 0, 0)
    canvas_draw_circle(&!c, 64, 64, 20, 0, 255, 0)
    // The top-most point of the circle should be colored
    let top = read_pixel(&c, 64, 44)
    let expected_green = 0 | (255 << 8) | (0 << 16)
    assert(top == expected_green)

    // 6. canvas_fill_circle — centre pixel and nearby are filled
    canvas_clear(&!c, 0, 0, 0)
    canvas_fill_circle(&!c, 64, 64, 10, 255, 128, 0)
    // Centre pixel must be filled
    let circ_center = read_pixel(&c, 64, 64)
    let expected_orange = 0 | (128 << 8) | (255 << 16)
    assert(circ_center == expected_orange)
    // Pixel well outside the radius must be unfilled
    let circ_outside = read_pixel(&c, 0, 0)
    assert(circ_outside == 0)

    // 7. font_glyph non-zero for printable char
    let g_a = font_glyph(65)  // 'A'
    assert(g_a != 0)
    let g_space = font_glyph(32)  // ' '
    assert(g_space == 0)

    // 8. font_draw_char writes some pixels
    canvas_clear(&!c, 0, 0, 0)
    font_draw_char(c.pixels, w, h, 65, 0, 0, 255, 255, 255)  // 'A'
    // At least the top row of 'A' glyph (bits 7-0 = row 0) should have pixels
    // Row 0 of 'A' glyph = 0x1C (from packed i64); check pixel at (2,0) which is bit 5
    let glyph_a = font_glyph(65)
    let row0 = glyph_a & 0xFF
    // Rather than hard-code bit positions, just check that at least one pixel in
    // the 8×8 box is white:
    var found_white = false
    var gy: i64 = 0
    while gy < 8 {
        var gx: i64 = 0
        while gx < 8 {
            let px = read_pixel(&c, gx, gy)
            if px != 0 {
                found_white = true
            }
            gx = gx + 1
        }
        gy = gy + 1
    }
    assert(found_white)

    heap_free(c.pixels as *mut i8)
    println("DISPLAY_HEADLESS_PASS")
}

