//@ run-pass
// f64 literal/local multiplication must use SSE (mulsd), not integer imul on the
// IEEE bit patterns. Regression test for the IrNop float-marker guard that vetoed
// float-marking f64 literals (result was 0).
fn abs_f64(x: f64) -> f64 { if x < 0.0 { return 0.0 - x } return x }
fn main() -> i64 with Mut {
    let a = 0.1 * 0.1 + 0.1 * 0.1     // 0.02
    let b = 0.5 * 0.5                 // 0.25
    if abs_f64(a - 0.02) > 0.0001 { return 1 }
    if abs_f64(b - 0.25) > 0.0001 { return 2 }
    return 0
}

//@ run-pass
//@ requires: madaros
// Engine-gated, not silenced. The CI suite runs souc-stage2, which is the
// lean_single self-host output, not Madaros -- see SOUNIO_TEST_SOUC_BIN in
// .github/workflows/ci.yml. ffi_exit is a Madaros native builtin (exit_group via syscall); lean_single
// does not carry it.
// Verified PASS on a Madaros built from this branch, on Slurm.
// extern "C" exit() must actually terminate the process — Track A Fase 3.4.
//
// Before fail-closed + the ffi_exit emitter (id 34, exit_group syscall), an
// unimplemented extern compiled to a silent no-op returning 0: this program
// would print the FAIL line and exit 1. With a real exit(0), the FAIL line
// is unreachable and the process ends rc=0 immediately after PASS.

extern "C" {
    fn exit(code: i32);
    fn getpid() -> i64;
}

fn main() -> i32 with IO, Panic {
    if getpid() > 0 {
        println("ffi_exit_terminates: PASS")
    }
    exit(0 as i32)
    println("ffi_exit_terminates: FAIL silent-noop exit")
    return 1
}

//@ run-pass
//@ requires: madaros
//@ expect-stdout: FIELD_IDENTITY_PASS

// Member resolution must not depend on declaration order.
//
// `arr[i].field` reaches field_idx_from_name_simple, which scans struct_layouts
// and returns the FIRST layout carrying that field name. Both structs below
// have `value`, at different slots, so whichever is registered first used to
// win for BOTH -- and the loser read the wrong offset:
//
//   A then B:   bs[i].value read A.value@0, returning B's pad (111, 333)
//   B then A:   as_[1].value read slot 1 of a ONE-field struct -- out of bounds
//
// #2126 fixed the Knowledge half of this by deferring the synthetic layout,
// which reversed the victim: ks[i].value on [Knowledge<f64>; N] then returned
// the VARIANCE, 0.010000 where 1.000000 belongs. Precedence in either
// direction is still "first name wins".
//
// The fix records the array local's ELEMENT type from its declared annotation,
// so the receiver has an identity to resolve against. Both halves are asserted
// here: neither struct may be sacrificed for the other, and Knowledge in an
// array must survive a user struct that spells `value`.

struct A { value: i64 }
struct B { pad: i64, value: i64 }

fn abs_f(x: f64) -> f64 {
    if x < 0.0 { return 0.0 - x }
    return x
}

fn main() -> i64 with Mut, Panic, Div, Alloc, Epistemic, IO {
    var as_: [A; 2] = [A { value: 7 }, A { value: 9 }]
    var bs: [B; 2] = [B { pad: 111, value: 222 }, B { pad: 333, value: 444 }]
    var ks: [Knowledge<f64>; 2] = [measure(1.0, uncertainty: 0.1), measure(3.0, uncertainty: 0.2)]

    print("as_[1].value="); print_int(as_[1].value); print("\n")
    print("bs[0].value=");  print_int(bs[0].value);  print("\n")
    print("bs[1].value=");  print_int(bs[1].value);  print("\n")
    print("bs[0].pad=");    print_int(bs[0].pad);    print("\n")
    print("ks[0].value=");  print_f64(ks[0].value);  print("\n")
    print("ks[1].value=");  print_f64(ks[1].value);  print("\n")

    let ok = as_[1].value == 9
        && bs[0].value == 222
        && bs[1].value == 444
        && bs[0].pad == 111
        && abs_f(ks[0].value - 1.0) < 1.0e-12
        && abs_f(ks[1].value - 3.0) < 1.0e-12
    if ok {
        print("FIELD_IDENTITY_PASS\n")
    } else {
        print("FIELD_IDENTITY_FAIL\n")
    }
    0
}

//@ run-pass
// for-in over a fixed-size array iterates exactly N times (logical length),
// not the allocation bucket capacity. Covers sum (reduction) + count.
// Returns 0 on success, nonzero on failure (exit codes are 8-bit, so we
// assert rather than return the raw 515).
fn main() -> i64 with Mut {
    var a: [i64; 5] = [0; 5]
    a[0] = 1
    a[1] = 2
    a[2] = 3
    a[3] = 4
    a[4] = 5
    var sum = 0
    var n = 0
    for v in a {
        sum = sum + v
        n = n + 1
    }
    if sum != 15 { return 1 }   // reduction over all 5 logical elements
    if n != 5 { return 2 }      // exactly N iterations, not the >=8 bucket
    return 0
}

